// ===== SQL Quest: healthcare storylines, practice challenges & skills checks =====
// Story world: Lumi Health, a community clinic. Arjun has just joined as a junior data analyst.
// Each chapter: STORY (why / when / how), PRACTICE (10-12 graded challenges), CHECK (skills check + feedback).
const SKILLS = {
  explore:'Exploring tables', keys:'Keys & relationships', cols:'Choosing columns', alias:'Aliases & calculations', distinct:'Unique values',
  where:'Filtering with WHERE', andor:'AND / OR logic', inlike:'IN, BETWEEN & LIKE', nulls:'Handling NULLs', sort:'Sorting', topn:'Top-N with LIMIT',
  agg:'Aggregate functions', groupby:'GROUP BY', having:'HAVING', join:'INNER JOIN', leftjoin:'LEFT JOIN & missing matches', multijoin:'Joining 3+ tables',
  case:'CASE logic', funcs:'Text & number functions', condagg:'Conditional counts', subq:'Subqueries', cte:'CTEs', exists:'EXISTS / anti-joins',
  rank:'Ranking windows', running:'Running totals', lag:'LAG / LEAD', kpi:'KPI reports', pct:'Percentages & rates', dml:'Changing data', txn:'Transactions',
  ddl:'Creating tables', constraints:'Constraints', views:'Views', setops:'UNION / INTERSECT / EXCEPT', dedupe:'Duplicates', dates:'Date math', text:'Text functions',
  funnel:'Funnels & conversion', retention:'Cohorts & retention', gaps:'Streaks & gaps', perf:'Indexes & performance', interview:'Interview problem-solving'
};

const STORY = {
1:{ cast:'👩‍💼 Priya, Head of Clinic Operations', ask:'"Welcome, Arjun! Everything about our clinic lives in the database: every patient, doctor and appointment. Before you analyse anything, get to know what\'s in there."',
  analogy:'A <b>table</b> is like the clinic\'s patient register. Each <b>row</b> is one patient\'s chart, and each <b>column</b> is one box on the intake form (name, birth date, insurance). The <b>primary key</b> works like a Medical Record Number (MRN): unique to every patient. A <b>foreign key</b> is that MRN written on a lab slip, so the slip can be matched back to the right chart.',
  why:'Hospitals and clinics have millions of records. Nobody scrolls through them. You ask the database questions in SQL, and it hands back exactly the rows you need in seconds.',
  when:['You join any team and need to see what data exists','Someone says "it\'s in the warehouse, can you pull it?"','Before every analysis: look at the raw rows first'],
  how:'<code>SELECT * FROM patients;</code> means "show me every column (*) from the patients table".' },
2:{ cast:'🩺 Dr. Amara Okoye, General Practice', ask:'"I need a simple list of our doctors and their specialties for the new website. Just the names and specialties, not salaries or hire dates!"',
  analogy:'A patient chart has 50 fields, but a referral letter only needs name, birth date and the reason. <b>SELECT</b> lets you photocopy only the boxes you need. <b>AS</b> renames a column header. <b>DISTINCT</b> is like listing each ward once, even if 200 patients are in them.',
  why:'Picking only the columns you need makes reports readable, protects private data (privacy rules say only use what\'s necessary) and makes queries faster.',
  when:['A manager wants "just the names and phone numbers"','You need a clean column header for a report','You want the list of unique values (all specialties, all cities)','You need a quick calculation (fee + tax)'],
  how:'<code>SELECT name, specialty FROM doctors;</code>, <code>SELECT visit_fee * 1.1 AS fee_with_tax</code>, <code>SELECT DISTINCT city FROM patients;</code>' },
3:{ cast:'👩‍⚕️ Nurse Manager Rosa', ask:'"Our diabetes educator wants to call every patient whose HbA1c is 6.5 or higher. Can you give me just those patients?"',
  analogy:'<b>WHERE</b> is triage. Out of everyone in the waiting room, it lets through only the people who meet the criteria. AND = both conditions must be true ("over 65 <i>and</i> on Medicare"). OR = either one is enough. NULL = a blank box on the form: unknown, not zero.',
  why:'Almost every real question has a filter: this month, this doctor, abnormal results only, no-shows only. Filtering early also keeps reports fast.',
  when:['"Only patients from Riverside"','"Appointments that were no-shows"','"Lab results above the healthy range"','"Patients with no insurance on file" (IS NULL)'],
  how:'<code>SELECT * FROM lab_results WHERE test = \'HbA1c\' AND value >= 6.5;</code>' },
4:{ cast:'🏥 Front Desk Lead Marcus', ask:'"Which 5 patients are the oldest? We\'re planning priority flu-shot calls, and I need them in order."',
  analogy:'<b>ORDER BY</b> is sorting the waiting list: by arrival time, by urgency, by name. <b>DESC</b> puts the biggest or latest first. <b>LIMIT</b> is "just show me the first 5 on the list".',
  why:'People act on the top of a list: the five most expensive prescriptions, the ten busiest days. Sorting turns raw rows into priorities.',
  when:['"Top 10 / bottom 10" questions','"Most recent" or "oldest" records','Any report someone will read top-down'],
  how:'<code>SELECT first_name, birth_date FROM patients ORDER BY birth_date LIMIT 5;</code>' },
5:{ cast:'📋 Clinic Director Dr. Chen', ask:'"For the board meeting I need totals: how many appointments each doctor had, and how much revenue each specialty brought in."',
  analogy:'<b>GROUP BY</b> is the daily ward census: instead of listing 200 patients, you write one line per ward with a count. <b>COUNT, SUM, AVG, MIN, MAX</b> are the numbers on that census line. <b>HAVING</b> filters whole wards, e.g. "only wards with more than 20 patients".',
  why:'Leaders make decisions from summaries, not from thousands of rows. GROUP BY is how almost every dashboard number gets made.',
  when:['"How many…per…" (visits per doctor, patients per city)','"Total / average…by…" (revenue by specialty)','"Which groups have more than…" (HAVING)'],
  how:'<code>SELECT doctor_id, COUNT(*) FROM appointments GROUP BY doctor_id;</code>' },
6:{ cast:'🔬 Lab Coordinator Kofi', ask:'"The lab results table only has patient IDs. The doctors want names next to the results. Can you match them up?"',
  analogy:'A <b>JOIN</b> matches the MRN on a lab slip to the MRN on the patient chart and staples them together. <b>INNER JOIN</b> keeps only slips that found their chart. <b>LEFT JOIN</b> keeps every chart, even patients with no lab slips yet (their lab columns are blank).',
  why:'Clinic data is split across tables so nothing is typed twice. Patients, doctors, appointments and labs each live in their own table. Real questions almost always need two or more of them together.',
  when:['You need names, but the table only has IDs','"Which patients have never booked?" (LEFT JOIN + IS NULL)','Revenue by specialty (appointments + doctors)'],
  how:'<code>SELECT p.first_name, l.test, l.value FROM lab_results l JOIN patients p ON p.patient_id = l.patient_id;</code>' },
7:{ cast:'🩸 Dr. Gita Rao, Endocrinology', ask:'"Can you label every HbA1c result as Normal, Prediabetes or Diabetes? Under 5.7 is normal, 5.7 to 6.4 is prediabetes, and 6.5 or above is diabetes."',
  analogy:'<b>CASE</b> works like a clinical decision rule: IF value ≥ 6.5 THEN "Diabetes", ELSE IF ≥ 5.7 THEN "Prediabetes", ELSE "Normal". <b>COALESCE</b> fills a blank on the form with a default, for example a missing insurance becomes "Self-pay".',
  why:'Raw numbers mean little to busy people. Categories (risk bands, age groups, on-time / late) make data instantly understandable.',
  when:['Turning numbers into bands (age groups, risk levels)','Replacing blanks (NULL → "Unknown")','Counting by condition (no-shows vs completed in one row)','Cleaning text (UPPER, initials)'],
  how:'<code>CASE WHEN value >= 6.5 THEN \'Diabetes\' WHEN value >= 5.7 THEN \'Prediabetes\' ELSE \'Normal\' END</code>' },
8:{ cast:'📊 Quality Lead Hannah', ask:'"Which patients visit more often than the average patient? I want to check whether our care plans are working."',
  analogy:'A <b>subquery</b> is a question inside a question: first work out the average number of visits, then find who\'s above it. A <b>CTE</b> (<code>WITH</code>) is a clinical pathway written as numbered steps. Step 1: count visits per patient. Step 2: compare to the average. Each step is easy to read and check.',
  why:'Real questions have several steps. Writing them as CTEs keeps your logic readable, easy to debug and easy for a colleague to review.',
  when:['"Above / below average" questions','Multi-step logic (first summarise, then filter or join)','You catch yourself copying the same subquery twice'],
  how:'<code>WITH visits AS (SELECT patient_id, COUNT(*) AS n FROM appointments GROUP BY patient_id) SELECT * FROM visits WHERE n > (SELECT AVG(n) FROM visits);</code>' },
9:{ cast:'🫀 Dr. Chen Wei, Cardiology', ask:'"For each patient, I want to see their visits in order, numbered 1, 2, 3…, plus how many days since the previous visit."',
  analogy:'A <b>window function</b> looks at a patient\'s whole timeline <i>without</i> merging the rows. Every visit stays on its own line, but you can number them (ROW_NUMBER), rank them (RANK), add a running total, or peek at the previous visit (LAG). <b>PARTITION BY patient</b> = "do this separately for each patient\'s chart".',
  why:'Timelines, rankings and "compared to last time" are everywhere in healthcare: follow-up gaps, readmissions, the busiest doctor each month.',
  when:['Numbering events per person (1st visit, 2nd visit…)','Top-N per group (top doctor per specialty)','Running totals and month-over-month change','Comparing a row to the previous one (LAG)'],
  how:'<code>ROW_NUMBER() OVER (PARTITION BY patient_id ORDER BY appt_date)</code>' },
10:{ cast:'💼 CFO Mr. Adams', ask:'"Every month I need one clinic scorecard: visits, revenue, no-show rate and our busiest specialty. Can SQL produce it automatically?"',
  analogy:'A KPI report is like the hospital\'s monthly quality scorecard: a few trusted numbers (visits, revenue, no-show rate) calculated the same way every time.',
  why:'This is the job: turning raw records into numbers leaders use. Analyst interviews often ask you to write exactly these queries.',
  when:['Monthly or weekly management reporting','Rates and percentages (no-show %, share of revenue)','Year-over-year or month-over-month comparisons'],
  how:'Combine everything: GROUP BY month, conditional counts (CASE), ROUND(100.0 * …), window functions for share-of-total.' },
11:{ cast:'🗂️ Records Officer Ines', ask:'"A patient moved city, three appointments need their status fixed, and we must remove two test records someone created. Can you update the database safely?"',
  analogy:'<b>INSERT</b> = registering a new patient. <b>UPDATE</b> = correcting a field on an existing chart. <b>DELETE</b> = removing a record. A <b>transaction</b> is the medication double-check: BEGIN, make your changes, check them, then COMMIT to save or ROLLBACK to undo.',
  why:'Analysts often maintain lookup and mapping tables and fix data issues. One careless UPDATE without WHERE can change every patient\'s record, so safe habits matter.',
  when:['Correcting a data error','Loading a new reference list (e.g. new drug codes)','Archiving or removing test records','Any change you might need to undo: use a transaction'],
  how:'<code>UPDATE patients SET city = \'Springfield\' WHERE patient_id = 7;</code> Always run the matching SELECT first!' },
12:{ cast:'🏗️ Data Architect Felix', ask:'"We\'re starting a vaccination programme. We need a new table that won\'t accept bad data, and a saved \'today\'s schedule\' view for the front desk."',
  analogy:'<b>CREATE TABLE</b> designs a new paper form. <b>Constraints</b> are the form\'s rules: required fields (NOT NULL), allowed values (CHECK dose between 1 and 3), and no duplicates (UNIQUE). A <b>view</b> is a saved report the front desk opens every morning: always up to date, never re-typed.',
  why:'Good structure prevents bad data at the door, which is far cheaper than cleaning it later. Views give everyone one agreed definition, e.g. of a "completed visit".',
  when:['A new process needs a new table','You want the database to reject invalid values','Many reports reuse the same query (make it a view)'],
  how:'<code>CREATE TABLE vaccinations (vacc_id INTEGER PRIMARY KEY, patient_id INTEGER NOT NULL, dose INTEGER CHECK (dose BETWEEN 1 AND 3));</code>' },
13:{ cast:'🧹 Data Quality Analyst Zara', ask:'"Why does my count of insured patients look wrong? And can you make one contact list of all patients and doctors for the holiday cards?"',
  analogy:'<b>UNION</b> stacks two lists into one, like merging the patient and staff phone lists. <b>INTERSECT</b> = people on both lists. <b>EXCEPT</b> = on the first list but not the second. <b>NULL</b>s are blanks on forms: they silently change counts and averages unless you handle them on purpose.',
  why:'Real data is messy. Blanks, duplicates and lists from different systems are daily problems. Spotting them is what makes an analyst trusted.',
  when:['Combining lists from two tables or systems','"Who is in A but not in B?"','Counts look odd (check NULLs and duplicates first)'],
  how:'<code>SELECT first_name FROM patients UNION SELECT name FROM doctors;</code>, <code>COALESCE(insurance, \'Self-pay\')</code>' },
14:{ cast:'📅 Scheduling Manager Victor', ask:'"How old is each patient? How many days pass between a patient\'s visits? And which weekday has the most no-shows?"',
  analogy:'Dates in SQL are like the clinic calendar. You can pull out the month, count days between two appointments, or find the month\'s start. Text functions are like tidying names on a form: capitals, initials, joining first and last name.',
  why:'Healthcare runs on time: ages, follow-up windows, days to appointment, seasonal flu peaks. Date skills turn up in almost every analyst task.',
  when:['Ages from birth dates','Days or weeks between events','Grouping by month, week or weekday','Cleaning and combining names'],
  how:'<code>strftime(\'%Y-%m\', appt_date)</code>, <code>julianday(b) - julianday(a)</code>, <code>first_name || \' \' || last_name</code>' },
15:{ cast:'📈 Population Health Lead Dr. Lind', ask:'"How many patients come back within 30 days of a visit? What\'s our no-show rate by doctor? Are January\'s new patients still coming back months later?"',
  analogy:'These are the clinic\'s classic analytics patterns. <b>Readmission / return within 30 days</b> uses LAG on each patient\'s timeline. <b>Funnels</b> track booked → attended. <b>Cohorts</b> follow everyone who started in the same month, like a clinical study.',
  why:'These patterns answer the questions healthcare and product teams ask most. Once you know the template, you can reuse it for any dataset.',
  when:['Return or readmission rates','Booked-to-attended (or visit-to-purchase) conversion','"Do new patients stick with us?" (retention)'],
  how:'<code>LAG(appt_date) OVER (PARTITION BY patient_id ORDER BY appt_date)</code>, then compare dates.' },
16:{ cast:'🧑‍💻 Interviewer from a Health-Tech Company', ask:'"Our appointments table has 50 million rows and the dashboard is slow. Also, walk me through how you would find each doctor\'s busiest month."',
  analogy:'An <b>index</b> is the front desk\'s alphabetical card file. Instead of checking every chart in the building (a full scan), you jump straight to the right drawer. Interviews test how you <i>think</i>: clarify the question, check the grain, build in steps, then test edge cases.',
  why:'Fast queries keep dashboards usable. A clear problem-solving method gets you hired.',
  when:['A query on a big table is slow','You filter or join on the same column all the time','Any SQL interview or take-home task'],
  how:'<code>CREATE INDEX idx_appt_patient ON appointments(patient_id);</code>, then <code>EXPLAIN QUERY PLAN …</code>' }
};

